import{_ as r,l as o,o as e,c as n,v as t,p as s,x as i,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"训练重放与可复现","description":"","frontmatter":{"title":"训练重放与可复现","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/training-replay.md","filePath":"llm/training-replay.md","lastUpdated":1789023840000}'),h={name:"llm/training-replay.md"};function c(A,a,m,u,_,B){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="训练重放与可复现" tabindex="-1">训练重放与可复现 <a class="header-anchor" href="#训练重放与可复现" aria-label="Permalink to &quot;训练重放与可复现&quot;">​</a></h1><div class="epigraph"><p>同一份配置、同一份数据游标、同一份 RNG，应能把损失尖峰再走一遍；做不到，就分不清是坏卡、非确定 CUDA 还是数据管道偷偷换了样本。</p><footer>—— 据 Pineau 等对机器学习可复现性的要求；对照框架确定性算法与大规模训练日志实践</footer></div><p><a href="/llm/straggler-mitigation">上一课</a>可能换过节点、调过预取。下一次损失尖峰时，需要回答：这是数据里的脏样本、非确定求和，还是硬件。本课不重讲 P99。缺口是训练重放：记录足以把全局 batch 再跑一遍的信息，以及哪些并行原语从一开始就放弃 bit 级相同。弹性事件必须出现在重放说明书里，而不是假装 run 是一条光滑曲线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 上的原子加、非确定 reduction、FlashAttention 的变体、异步保存与训练抢流，都会让两次前向差一个 ULP，几天之后差出可见损失。完全 bit 级相同在万卡上通常不作为目标。可复现的工程定义应分层：同一检查点、同一微批、同一并行计划下，损失应对拍到规定的容差；跨弹性事件只要求 token 会计正确。缺的是把这层定义写进配方，并保存重放所需的种子与游标。</p><p>数据管道是最常见的假非确定：多进程解码顺序、gzip 并行、过滤阈值随时间改。去污染指纹库一更新，同一游标会对上不同文档。重放必须冻结指纹库版本。</p><h3 id="rng-有多份" tabindex="-1">RNG 有多份 <a class="header-anchor" href="#rng-有多份" aria-label="Permalink to &quot;RNG 有多份&quot;">​</a></h3><p>Python、NumPy、框架、CUDA、Dropout、路由噪声、数据 shuffle，各有种子。只设一个 <code>seed=42</code> 不够。MoE 路由若用噪声，种子要进检查点。FIM 挖空位置、α 采样的多项分布，同理。</p><p><span class="marginnote">确定性算法开关会严重降速。应作为「重放模式」打开，而不是生产默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个全局 step 记录：检查点 id、数据游标、全部 RNG、并行计划、软件版本（含注意力核）。尖峰时：拉起同计划、开确定性算法、只跑该微批或其后 N 步，对比激活范数与损失。若单卡重放正常、多卡失败，查集合通信与落后者。若多卡也失败，查数据解码。</p><p>弹性后在日志打 <code>nondet_event=elastic</code>。审计曲线时分段，不把事件两侧点在同一条「可复现」线上。异步检查点的「latest」指针也要进记录，以免重放加载了后一次损坏点。</p><h3 id="与评测" tabindex="-1">与评测 <a class="header-anchor" href="#与评测" aria-label="Permalink to &quot;与评测&quot;">​</a></h3><p>训练中评测的采样若无种子，曲线不可比。评测集版本与去污染清单版本一并冻结。</p><p><span class="marginnote">对拍 1F1B 与 DualPipe 时，容差要比「两次相同调度」更宽，但仍应排除数量级错误。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浮点结合律在并行归约上不成立，bit 级相同需要固定归约树。大规模训练选择固定计划 + 记录种子，把不确定性关进声明过的盒子（弹性、非确定核）。重放是把盒子外的变量全部钉死，看盒子内是否仍爆炸——若仍爆炸，才是算法或数据。</p>',17)),(e(),s(E,null,{default:i(()=>[p(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22step%20%E6%97%A5%E5%BF%97%EF%BC%9A%E6%B8%B8%E6%A0%87%20%2F%20RNG%20%2F%20%E8%AE%A1%E5%88%92%22%5D%20--%3E%20REP%5B%22%E9%87%8D%E6%94%BE%E6%A8%A1%E5%BC%8F%EF%BC%9A%E7%A1%AE%E5%AE%9A%E6%80%A7%E6%A0%B8%22%5D%0A%20%20REP%20--%3E%20CMP%5B%22%E5%AF%B9%E6%AF%94%E6%8D%9F%E5%A4%B1%E4%B8%8E%E6%BF%80%E6%B4%BB%E8%8C%83%E6%95%B0%22%5D%0A%20%20CMP%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%3F%22%5D%0A%20%20CMP%20--%3E%20COMM%5B%22%E9%80%9A%E4%BF%A1%20%2F%20%E7%A1%AC%E4%BB%B6%3F%22%5D%0A%20%20CMP%20--%3E%20ALG%5B%22%E7%AE%97%E6%B3%95%3F%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>重放不修复故障率，只缩短诊断。它也不能在换了词表之后对拍旧 run。下一课把「训练中评测」从偶然的 <code>print(loss)</code> 收成有预算、不挡训练、可重放的信号管道，否则早期信号本身成为不可复现的噪声源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲慢卡治理；只补分层可复现与微批重放。</li><li>生产不追求万卡 bit 级；重放模式才开确定性核。</li><li>冻结数据、指纹、种子、并行计划；弹性单独标注。</li><li>多份 RNG 全部进检查点。</li><li>出处：Pineau et al. 对可复现性的讨论；PyTorch 确定性算法；MegaScale / Llama 3 训练日志实践。</li></ul>',4))])}const b=r(h,[["render",c]]);export{f as __pageData,b as default};
